const $=s=>document.querySelector(s),all=groups.flatMap(g=>g.needs),key='ombaliz-besoins-v1';let state={needs:{},reflections:{},actions:{}},family=0,view='explore';try{const s=JSON.parse(localStorage.getItem(key));if(s&&s.needs&&s.reflections&&s.actions)state=s}catch{}state.patient=state.patient||{};function renderPatient(){for(const x of document.querySelectorAll("[data-patient]"))x.value=state.patient[x.dataset.patient]||""}renderPatient();const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const val=id=>state.needs[id]||{};function save(){try{localStorage.setItem(key,JSON.stringify(state));$('#save').textContent='✓ Réponses enregistrées sur cet appareil.'}catch{$('#save').textContent='Enregistrement indisponible : téléchargez votre bilan avant de quitter.'}progress()}
function progress(){let n=all.filter(n=>val(n.id).importance!=null&&val(n.id).satisfaction!=null).length;$('#progress').textContent=n+' / 31 besoins complétés';$('#bar').style.width=(n/31*100)+'%'}
function show(v){view=v;for(const x of ['explore','bilan','action'])$('#'+x).hidden=x!==v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='bilan')bilan();if(v==='action')actions();}
function cards(){let q=$('#search').value.toLocaleLowerCase('fr');$('#familytitle').textContent=q?'Les besoins qui vous parlent':groups[family].title;$('#familysub').textContent=q?'Résultats dans les cinq familles':groups[family].sub;$('#families').innerHTML=groups.map((g,i)=>`<button data-family="${i}" class="${i===family?'active':''}" aria-pressed="${i===family}">${String(i+1).padStart(2,'0')} · ${g.title}</button>`).join('');let items=q?all.filter(n=>(n.name+' '+n.desc).toLocaleLowerCase('fr').includes(q)):groups[family].needs;$('#cards').innerHTML=items.map(n=>{let v=val(n.id);return `<article class="card"><div class="cardhead"><h3>${n.name}</h3><button class="priority" data-priority="${n.id}" aria-pressed="${!!v.priority}">${v.priority?'★':'☆'} Ma priorité</button></div><p>${n.desc}</p><label for="imp-${n.id}" class="scalehead"><span>Importance pour moi</span><b id="out-${n.id}">${v.importance??'À préciser'}${v.importance!=null?' / 10':''}</b></label><input id="imp-${n.id}" data-id="${n.id}" type="range" min="0" max="10" step="1" value="${v.importance??5}" aria-describedby="hint-${n.id}"><div class="ends" id="hint-${n.id}"><span>0 · Peu important</span><span>10 · Essentiel</span></div><div class="scalehead" id="sat-${n.id}">Satisfaction aujourd’hui <b id="satout-${n.id}">${v.satisfaction??'À préciser'}${v.satisfaction?' / 5':''}</b></div><div class="ratings" role="group" aria-labelledby="sat-${n.id}">${[1,2,3,4,5].map(i=>`<button aria-label="${n.name} : satisfaction ${i} sur 5" aria-pressed="${v.satisfaction===i}" data-sat="${i}" data-id="${n.id}">${i}</button>`).join('')}</div><div class="ends"><span>Très peu satisfait</span><span>Totalement satisfait</span></div><details ${v.note?'open':''}><summary>Mettre mes mots sur ce besoin</summary><label for="note-${n.id}">Dans ma vie, cela ressemble à…</label><textarea id="note-${n.id}" data-note="${n.id}" rows="3" placeholder="Une situation, un ressenti, une envie…">${esc(v.note)}</textarea></details></article>`}).join('')||'<p>Aucun besoin trouvé. Essayez un autre mot.</p>';$('#prev').disabled=family===0;$('#next').textContent=family===4?'Voir mon bilan →':'Famille suivante →';progress()}
const questions=['Quels besoins sont les mieux nourris ? Qu’est-ce qui m’a aidé ?','Quels besoins sont les moins satisfaits ? Quel impact dans mon quotidien ?','Qu’est-ce que cela changerait pour moi de mieux répondre à ces besoins ?'];
function bilan(){let sorted=[...all].sort((a,b)=>(val(b.id).importance??-1)-(val(a.id).importance??-1));$('#summary').innerHTML='<div class="row"><b>Mon besoin</b><b>Importance / 10</b><b>Satisfaction / 5</b></div>'+sorted.map(n=>{let v=val(n.id);return `<div class="row"><span>${v.priority?'★ ':''}${n.name}</span><span>${v.importance??'—'}<div class="meter"><i style="width:${(v.importance??0)*10}%"></i></div></span><span>${v.satisfaction??'—'}</span></div>`}).join('');$('#reflections').innerHTML=questions.map((q,i)=>`<label class="reflection">${q}<textarea data-ref="${i}" rows="3" style="width:100%;display:block">${esc(state.reflections[i])}</textarea></label>`).join('')}
function actions(){let selected=all.filter(n=>val(n.id).priority);$('#actions').innerHTML=selected.length?selected.map(n=>{let a=state.actions[n.id]||{};return `<article class="action"><h3>${n.name}</h3><label>Un petit pas concret<textarea data-action="step" data-id="${n.id}" rows="3" placeholder="Quoi, quand, avec qui ?">${esc(a.step)}</textarea></label><label>Ce qui pourrait m’aider<textarea data-action="help" data-id="${n.id}" rows="2">${esc(a.help)}</textarea></label><label>Quand essayer ?<input type="date" data-action="date" data-id="${n.id}" value="${esc(a.date)}"></label><label>Faisabilité : <b id="feas-${n.id}">${a.feas??'À préciser'}</b> / 100<input type="range" min="0" max="100" step="5" value="${a.feas??50}" data-action="feas" data-id="${n.id}"></label><div class="ends"><span>0 · Pas possible actuellement</span><span>100 · Tout à fait possible</span></div><p>Si ce pas paraît trop difficile, comment le rendre plus petit ?</p></article>`}).join(''):'<div class="panel"><p>Vous n’avez pas encore choisi de priorité.</p><button data-view="explore">Explorer mes besoins</button></div>'}
function report(){return 'MON BILAN DES BESOINS — Ombaliz Thérapie\n'+new Date().toLocaleDateString('fr-FR')+'\nAdresse mail : '+(state.patient.email||'Non renseignée')+'\nTéléphone : '+(state.patient.phone||'Non renseigné')+'\n\n'+all.map(n=>{let v=val(n.id),a=state.actions[n.id]||{};return (v.priority?'★ PRIORITÉ — ':'')+n.name+'\nImportance : '+(v.importance??'Non renseignée')+'/10 | Satisfaction : '+(v.satisfaction??'Non renseignée')+'/5'+(v.note?'\nMes mots : '+v.note:'')+(v.priority?'\nPetit pas : '+(a.step||'À préciser')+'\nSoutien : '+(a.help||'À préciser')+'\nDate : '+(a.date||'À préciser')+'\nFaisabilité : '+(a.feas??'Non renseignée')+'/100':'')}).join('\n\n')+'\n\n'+questions.map((q,i)=>q+'\n'+(state.reflections[i]||'Non renseigné')).join('\n\n')+'\n\nSupport de réflexion, sans valeur diagnostique.\ncontact@ombaliz.com'}
function dialog(html){$('#dialogbody').innerHTML=html;$('#dialog').showModal()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view)show(b.dataset.view);if(b.dataset.family!=null){family=+b.dataset.family;$('#search').value='';cards()}if(b.dataset.priority!=null){let id=b.dataset.priority,v=val(id);if(!v.priority&&all.filter(n=>val(n.id).priority).length>=3){dialog('<h2>Trois priorités à la fois</h2><p>Désélectionnez une priorité pour en choisir une autre.</p>');return}state.needs[id]={...v,priority:!v.priority};save();cards()}if(b.dataset.sat){let id=b.dataset.id;state.needs[id]={...val(id),satisfaction:+b.dataset.sat};save();b.parentElement.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#satout-'+id).textContent=b.dataset.sat+' / 5'}});
document.addEventListener('input',e=>{let x=e.target;if(x.dataset.patient){state.patient[x.dataset.patient]=x.value;save()}if(x.matches('input[data-id]:not([data-action])')){let id=x.dataset.id;state.needs[id]={...val(id),importance:+x.value};$('#out-'+id).textContent=x.value+' / 10';save()}if(x.dataset.note!=null){state.needs[x.dataset.note]={...val(x.dataset.note),note:x.value};save()}if(x.dataset.ref!=null){state.reflections[x.dataset.ref]=x.value;save()}if(x.dataset.action){let id=x.dataset.id;state.actions[id]={...state.actions[id],[x.dataset.action]:x.dataset.action==='feas'?+x.value:x.value};if(x.dataset.action==='feas')$('#feas-'+id).textContent=x.value;save()}});
$('#search').oninput=cards;$('#prev').onclick=()=>{family=Math.max(0,family-1);cards()};$('#next').onclick=()=>{if(family===4)show('bilan');else{family++;cards()}$('#main').scrollIntoView({behavior:'smooth'})};$('#close').onclick=()=>$('#dialog').close();$('#download').onclick=downloadNeedsPDF;$('#email').onclick=()=>{let body=report();if(body.length>5500){$('#exportstatus').textContent='Votre bilan est long : téléchargez-le puis joignez-le au courriel.';location.href='mailto:contact@ombaliz.com?subject='+encodeURIComponent('Mon bilan des besoins')+'&body='+encodeURIComponent('Bonjour,\nJe souhaite partager mon bilan des besoins, que je joins à ce courriel.')}else location.href='mailto:contact@ombaliz.com?subject='+encodeURIComponent('Mon bilan des besoins')+'&body='+encodeURIComponent(body)};$('#print').onclick=()=>{let pre=document.createElement('pre');pre.id='printreport';pre.textContent=report();document.body.append(pre);window.print();pre.remove()};$('#install').onclick=()=>dialog('<h2>Votre espace sur téléphone</h2><p><b>iPhone / iPad :</b> ouvrez ce site dans Safari, touchez Partager, puis « Sur l’écran d’accueil ».</p><p><b>Android :</b> ouvrez ce site dans Chrome, puis le menu ⋮ et « Ajouter à l’écran d’accueil » ou « Installer l’application ».</p><p>Il s’agit d’une application web, sans téléchargement depuis les stores. Les réponses ne se synchronisent pas entre appareils.</p>');$('#privacy').onclick=()=>{dialog('<h2>Vous gardez la main</h2><p>Vos réponses sont enregistrées dans ce navigateur sur cet appareil, sans envoi automatique au thérapeute. Elles peuvent être accessibles aux autres utilisateurs de cet appareil. Effacer les données du navigateur les supprimera.</p><p>Le bouton courriel ouvre votre messagerie ; vous vérifiez le contenu avant de l’envoyer. Les données de santé envoyées par courriel ne bénéficient pas d’un canal médical sécurisé.</p><button id="erase">Effacer toutes mes réponses</button>');$('#erase').onclick=()=>{if(confirm('Effacer définitivement toutes vos réponses sur cet appareil ?')){state={needs:{},reflections:{},actions:{},patient:{}};renderPatient();save();cards();show('explore');$('#dialog').close()}}};cards();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
